-- Some executors (Hydrogen iOS, older builds, certain Synapse forks) silently
-- fail or freeze on TweenService:Create / :Play. To guarantee the key-UI
-- works on ALL executors, tween() now sets the target properties instantly
-- to their final values instead of animating. The UI ends up at the same
-- visual "rest state" the tweens would have produced, just without motion.
-- utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)
local function tween(obj, props, _dur, _style, _dir)
    if not obj or not props then return end
    pcall(function()
        for k, v in pairs(props) do
            obj[k] = v
        end
    end)
end
local function corner(p, r)
    local c = Instance.new("UICorner"); c.CornerRadius = UDim.new(0, r or T.Radius); c.Parent = p; return c
end
local function stroke(p, col, thick, trans)
    local s = Instance.new("UIStroke"); s.Color = col or T.Border; s.Thickness = thick or 1; s.Transparency = trans or 0.5; s.Parent = p; return s
end
local function gradient(p, c1, c2, rot)
    local g = Instance.new("UIGradient")
    g.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, c1), ColorSequenceKeypoint.new(1, c2)})
    g.Rotation = rot or 0; g.Parent = p; return g
end
local function padding(p, t, b, l, r)
    local pd = Instance.new("UIPadding"); pd.PaddingTop = UDim.new(0,t); pd.PaddingBottom = UDim.new(0,b); pd.PaddingLeft = UDim.new(0,l); pd.PaddingRight = UDim.new(0,r); pd.Parent = p; return pd
end
