local function safeParent(gui)
    local parented = false
    if not RunService:IsStudio() then
        if syn and syn.protect_gui then
            pcall(function() syn.protect_gui(gui); gui.Parent = CoreGui; parented = true end)
        end
        if not parented and gethui then
            pcall(function() gui.Parent = gethui(); parented = true end)
        end
        if not parented and get_hidden_gui then
            pcall(function() gui.Parent = get_hidden_gui(); parented = true end)
        end
    end
    if not parented then
        pcall(function()
            gui.Parent = (RunService:IsStudio() and LocalPlayer:WaitForChild("PlayerGui", 5)) or CoreGui
        end)
    end
end
safeParent(Screen)
