local statusIconImg = Instance.new("ImageLabel")
statusIconImg.Size = UDim2.new(0, 12, 0, 12)
statusIconImg.BackgroundTransparency = 1
statusIconImg.ZIndex = 15
statusIconImg.Parent = statusMsg

local updatingStatus = false
local function updateStatusLayout()
    if updatingStatus then return end
    updatingStatus = true
    
    local text = statusMsg.Text
    local emojiMap = {
        ["🔑"] = "rbxassetid://116918931002434",
        ["💬"] = "rbxassetid://86432989388834",
        ["⚡"] = "rbxassetid://109718589733073",
        ["🗡"] = "rbxassetid://71867984579031",
        ["🛡"] = "rbxassetid://71867984579031",
        ["⭐"] = "rbxassetid://92253403464658",
        ["✨"] = "rbxassetid://92253403464658",
        ["🔗"] = "rbxassetid://116378866141355",
        ["⏳"] = "rbxassetid://136533241128438",
        ["⚠"] = "rbxassetid://112102474509324",
        ["❌"] = "rbxassetid://116396312853810",
        ["📋"] = "rbxassetid://105021692319787",
        ["⚙"] = "rbxassetid://106205298246017",
        ["🥚"] = "rbxassetid://87706885156127",
        ["✅"] = "rbxassetid://105979545056636"
    }
    
    local foundAsset = nil
    local cleanText = text
    for em, asset in pairs(emojiMap) do
        if text:sub(1, #em) == em then
            foundAsset = asset
            cleanText = text:sub(#em + 1):gsub("^%s+", "")
            break
        end
    end
    
    if foundAsset then
        statusIconImg.Image = foundAsset
        statusIconImg.Visible = true
        statusIconImg.ImageColor3 = statusMsg.TextColor3
        
        local width = statusMsg.AbsoluteSize.X > 0 and statusMsg.AbsoluteSize.X or 300
        local leftOffset = (width / 2) - (statusMsg.TextBounds.X / 2) - 16
        statusIconImg.Position = UDim2.new(0, leftOffset, 0.5, -6)
        
        statusMsg.Text = cleanText
    else
        statusIconImg.Visible = false
    end
    
    updatingStatus = false
end

statusMsg:GetPropertyChangedSignal("Text"):Connect(updateStatusLayout)
statusMsg:GetPropertyChangedSignal("TextBounds"):Connect(updateStatusLayout)
statusMsg:GetPropertyChangedSignal("TextColor3"):Connect(function()
    statusIconImg.ImageColor3 = statusMsg.TextColor3
end)
